mapper.select:
SELECT uu.`name`, uo.org_name department, td.`name` position, DATE_FORMAT(pt.start_time,'%Y年%c月%e日') carUseDate, pt.`start`, pt.destination, pt.start_time startTime, pt.end_time endTime, pa.accident_scene_img accidentSceneImg, pa.responsibility_confirm_img responsibilityConfirmImg, pa.detail FROM pubcar_accident pa LEFT JOIN pubcar_trip pt ON pt.trip_id = pa.trip_id AND pt.status_cd = '0' LEFT JOIN u_user uu ON uu.user_id = pt.user_id AND uu.status_cd = '0' LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id AND uosr.status_cd = '0' LEFT JOIN u_org uo ON uo.org_id = uosr.org_id AND uo.status_cd = '0' LEFT JOIN t_dict td ON td.status_cd = uosr.rel_cd AND td.table_name = 'u_org_staff_rel' AND td.table_columns = 'rel_cd' WHERE pa.status_cd = '0'
AND pt.start_time >= #{lessCarUseDate}
AND pt.start_time <= #{moreCarUseDate}
AND uo.org_name LIKE concat('%',#{department},'%')
AND td.`name` LIKE concat('%',#{position},'%')
AND uu.`name` LIKE concat('%',#{name},'%')
ORDER BY pa.create_time DESC
limit #{page}, #{row}

SELECT COUNT(1) count FROM pubcar_accident pa LEFT JOIN pubcar_trip pt ON pt.trip_id = pa.trip_id AND pt.status_cd = '0' LEFT JOIN u_user uu ON uu.user_id = pt.user_id AND uu.status_cd = '0' LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id AND uosr.status_cd = '0' LEFT JOIN u_org uo ON uo.org_id = uosr.org_id AND uo.status_cd = '0' LEFT JOIN t_dict td ON td.status_cd = uosr.rel_cd AND td.table_name = 'u_org_staff_rel' AND td.table_columns = 'rel_cd' WHERE pa.status_cd = '0'
AND pt.start_time >= #{lessCarUseDate}
AND pt.start_time <= #{moreCarUseDate}
AND uo.org_name LIKE concat('%',#{department},'%')
AND td.`name` LIKE concat('%',#{position},'%')
AND uu.`name` LIKE concat('%',#{name},'%')
